      <span>{field.label} <b>Required</b></span>
      {field.email ? <span className={cx("field-control-with-icon [position:relative] [display:flex] [align-items:center] [&_>_svg]:[position:absolute] [&_>_svg]:[left:0.75rem] [&_>_svg]:[color:var(--neutral-500)] [&_input]:[padding-left:2.25rem]")}><Mail size={17} /><input type="email" value={draft[field.key]} onChange={(event) => onChange(field.key, event.target.value)} aria-invalid={errors.has(field.key)} /></span> : <input value={draft[field.key]} onChange={(event) => onChange(field.key, event.target.value)} aria-invalid={errors.has(field.key)} />}
      {errors.has(field.key) && <small className={cx("field-error [display:block] [margin-top:0.35rem] [color:var(--danger)] [font-size:0.7rem] [font-weight:620]")}>{field.email ? "Enter a valid email address." : "This contact is required."}</small>}
