function OwnerDialog({ owner, onClose, onSave }: { owner: OwnerRecord; onClose: () => void; onSave: (owner: OwnerRecord) => void }) {
  const [draft, setDraft] = useState(owner);
  const [submitted, setSubmitted] = useState(false);
  const valid = Boolean(draft.primaryName.trim() && draft.backupName.trim() && isEmail(draft.primaryEmail) && isEmail(draft.backupEmail));
  const fields: Array<{ key: keyof OwnerRecord; label: string; email?: boolean }> = [
    { key: "primaryName", label: "Primary Owner" }, { key: "primaryEmail", label: "Primary Owner email", email: true },
    { key: "backupName", label: "Backup Owner" }, { key: "backupEmail", label: "Backup Owner email", email: true },
  ];
  return <div className={cx("dialog-layer [position:fixed] [z-index:100] [inset:0] [display:grid] [place-items:center]")}><button className={cx("dialog-backdrop [position:absolute] [inset:0] [border:0] [background:rgb(2_6_23_/_0.48)] [backdrop-filter:blur(3px)]")} aria-label="Close owner editor" onClick={onClose} /><section className={cx("dialog [position:relative] [width:min(560px,_calc(100%_-_2rem))] [max-height:calc(100vh_-_2rem)] [overflow-y:auto] [border:1px_solid_var(--border-glass)] [border-radius:var(--radius-xl)] [background:var(--surface-elevated)] [box-shadow:var(--shadow-3)] [animation:dialog-in_180ms_ease-out]")} role="dialog" aria-modal="true" aria-labelledby="owner-dialog-title">
    <div className={cx("dialog__header [display:flex] [align-items:center] [justify-content:space-between] [gap:1rem] [padding:1rem_1.1rem] [border-bottom:1px_solid_var(--neutral-200)] [&_h2]:[margin-top:0.2rem] [&_h2]:[font-size:1.2rem]")}><div><p className={cx("eyebrow [color:var(--kc-700)] [font-size:0.75rem] [font-weight:700] [letter-spacing:0.02em] [line-height:1.3] [.readonly-action_p&]:[margin-bottom:0.3rem] [.setup-complete_&]:[margin-top:1rem]")}>{owner.category}</p><h2 id="owner-dialog-title">Edit {owner.program} owners</h2></div><IconButton label="Close dialog" onClick={onClose}><X size={20} /></IconButton></div>
    <InlineMessage tone="info" title="Both owners can edit">The labels show accountability; Primary and Backup Owners have the same site permissions.</InlineMessage>
    <div className={cx("dialog-form [display:grid] [gap:1rem] [padding:1.1rem] form-grid [display:grid] [grid-template-columns:repeat(2,_minmax(0,_1fr))] [gap:1rem_1.15rem] [padding:1.2rem] max-[740px]:[grid-template-columns:1fr]")}>{fields.map((field) => {
      const value = draft[field.key];
      const invalid = submitted && (!String(value).trim() || (field.email && !isEmail(String(value))));
      return <label className={cx("field [display:grid] [min-width:0] [gap:0.4rem] [&_>_span:first-child]:[display:flex] [&_>_span:first-child]:[align-items:center] [&_>_span:first-child]:[justify-content:space-between] [&_>_span:first-child]:[color:var(--neutral-700)] [&_>_span:first-child]:[font-size:0.78rem] [&_>_span:first-child]:[font-weight:650] [&_b]:[color:var(--danger)] [&_b]:[font-size:0.64rem] [&_b]:[letter-spacing:0.01em] [&_input]:[width:100%] [&_input]:[border:1px_solid_var(--neutral-300)] [&_input]:[border-radius:var(--radius-md)] [&_input]:[outline:0] [&_input]:[background:var(--surface-input)] [&_input]:[color:var(--neutral-900)] [&_input]:[padding:0.68rem_0.75rem] [&_input]:[font-size:0.86rem] [&_input]:[transition:border-color_120ms_ease,_box-shadow_120ms_ease] [&_textarea]:[width:100%] [&_textarea]:[border:1px_solid_var(--neutral-300)] [&_textarea]:[border-radius:var(--radius-md)] [&_textarea]:[outline:0] [&_textarea]:[background:var(--surface-input)] [&_textarea]:[color:var(--neutral-900)] [&_textarea]:[padding:0.68rem_0.75rem] [&_textarea]:[font-size:0.86rem] [&_textarea]:[transition:border-color_120ms_ease,_box-shadow_120ms_ease] [&_input]:[min-height:42px] [&_textarea]:[resize:vertical] [&_textarea]:[line-height:1.5] [&_input:focus]:[border-color:var(--kc-600)] [&_input:focus]:[box-shadow:0_0_0_3px_var(--kc-100)] [&_textarea:focus]:[border-color:var(--kc-600)] [&_textarea:focus]:[box-shadow:0_0_0_3px_var(--kc-100)] [.requirement-header_>_&]:[margin-top:1rem]", invalid && "field--invalid [&_input]:[border-color:var(--danger)]! [&_input]:[box-shadow:0_0_0_3px_var(--danger-surface)] [&_textarea]:[border-color:var(--danger)]! [&_textarea]:[box-shadow:0_0_0_3px_var(--danger-surface)] [&_select]:[border-color:var(--danger)]! [&_select]:[box-shadow:0_0_0_3px_var(--danger-surface)]")} key={field.key}><span>{field.label} <b>Required</b></span><input type={field.email ? "email" : "text"} value={value} onChange={(event) => setDraft((current) => ({ ...current, [field.key]: event.target.value }))} aria-invalid={invalid} />{invalid && <small className={cx("field-error [display:block] [margin-top:0.35rem] [color:var(--danger)] [font-size:0.7rem] [font-weight:620]")}>{field.email ? "Enter a valid email address." : "Enter an owner name."}</small>}</label>;
    })}</div>
    <div className={cx("dialog__footer [display:flex] [align-items:center] [justify-content:flex-end] [gap:1rem] [padding:1rem_1.1rem] [border-top:1px_solid_var(--neutral-200)] max-[740px]:[align-items:stretch] max-[740px]:[flex-direction:column-reverse]")}><Button variant="tertiary" onClick={onClose}>Cancel</Button><Button variant="primary" icon={<Save size={17} />} onClick={() => { setSubmitted(true); if (valid) onSave(draft); }}>Save owners</Button></div>
  </section></div>;
}

export function OwnersScreen() {
  const { ownerRecords, updateOwner, notify } = useSites();
  const [query, setQuery] = useState("");
  const [category, setCategory] = useState("all");
  const [editing, setEditing] = useState<OwnerRecord | null>(null);
  const [savedName, setSavedName] = useState("");
  const filtered = ownerRecords.filter((owner) => `${owner.program} ${owner.primaryName} ${owner.backupName}`.toLowerCase().includes(query.toLowerCase()) && (category === "all" || owner.category === category));
  return (
    <div className={cx("page-container [width:100%] [padding:clamp(1.5rem,_2.4vw,_2.35rem)_var(--page-gutter)_4rem] max-[740px]:[padding-top:1.25rem] max-[740px]:[padding-bottom:3.5rem]")}>
      <PageHeader eyebrow="Site workspace" title="Program & standard owners" description="Primary and Backup Owners have equal edit permissions for this assigned site." />
      {savedName ? <InlineMessage tone="success" title={`${savedName} owners updated`}>The new Primary and Backup Owner details are saved for this site.</InlineMessage> : <InlineMessage tone="info" title="Equal permissions">Primary and Backup Owner labels identify responsibility only. Both roles can maintain the same assessment content.</InlineMessage>}
      <div className={cx("content-toolbar [display:flex] [align-items:center] [gap:0.7rem] [margin-top:1.25rem] max-[740px]:[align-items:stretch] max-[740px]:[flex-direction:column]")} data-tour="owners-controls">
        <label className={cx("search-control [display:flex] [min-width:250px] [min-height:42px] [flex:1] [align-items:center] [gap:0.55rem] [border:1px_solid_var(--neutral-300)] [border-radius:var(--radius-md)] [background:var(--surface-input)] [padding:0_0.75rem] [color:var(--neutral-500)] [&:focus-within]:[border-color:var(--kc-600)] [&:focus-within]:[box-shadow:0_0_0_3px_var(--kc-100)] [&_input]:[min-width:0] [&_input]:[flex:1] [&_input]:[border:0] [&_input]:[outline:0] [&_input]:[background:transparent] [&_input]:[color:var(--neutral-900)] [&_input]:[font-size:0.85rem] [.dashboard-filter-bar_&]:[flex:0_1_420px] [.dashboard-filter-bar_&]:[min-width:0] [.dashboard-filter-bar--expanded_&]:[flex:0_1_420px] [.dashboard-filter-bar--expanded_&]:[min-width:0] [.filter-row_&]:[flex:0_1_420px] [.filter-row_&]:[min-width:0] [.content-toolbar_&]:[flex:0_1_420px] [.content-toolbar_&]:[min-width:0] [.requirement-main--editor_.checkbox-list__toolbar_&]:[flex:1_1_320px] [.requirement-main--editor_.checkbox-list__toolbar_&]:[min-width:0] [.checkbox-list__toolbar_&_>_input]:[min-height:0] [.checkbox-list__toolbar_&_>_input]:[border:0]! [.checkbox-list__toolbar_&_>_input]:[border-radius:0] [.checkbox-list__toolbar_&_>_input]:[box-shadow:none]! [.checkbox-list__toolbar_&_>_input]:[outline:0]! [.checkbox-list__toolbar_&_>_input]:[padding:0] [.checkbox-list__toolbar_&]:[flex:0_1_420px] [.checkbox-list__toolbar_&]:[min-width:0] max-[1100px]:[.dashboard-filter-bar_&]:[width:100%] max-[1100px]:[.dashboard-filter-bar_&]:[flex-basis:100%] max-[1100px]:[.dashboard-filter-bar_&]:[min-width:0] max-[740px]:[width:100%] max-[740px]:[max-width:none] max-[740px]:[min-width:0] max-[740px]:[flex-basis:auto]!")}><Search size={18} /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search programs, standards, or people" /></label>
        <Select
          label="Filter owner category"
          icon={<Filter size={18} />}
          value={category}
          onChange={setCategory}
          options={[
            { value: "all", label: "All categories" },
            { value: "Operating System", label: "Operating System" },
            { value: "Performance Standard", label: "Performance Standard" },
          ]}
        />
      </div>
      {filtered.length ? <div className={cx("owner-grid [display:grid] [grid-template-columns:repeat(2,_minmax(0,_1fr))] [gap:1rem] [margin-top:1rem] max-[740px]:[grid-template-columns:1fr]")} data-tour="owner-list">{filtered.map((owner) => <OwnerCard owner={owner} onEdit={setEditing} key={owner.id} />)}</div> : <EmptyState icon={<Search size={26} />} title="No owners found" description="Try another name or category." />}
      {editing && <OwnerDialog owner={editing} onClose={() => setEditing(null)} onSave={(owner) => {
        updateOwner(owner);
        // Split by audience: /owners is site-contributor-only, so an administrator given that
        // link would be redirected to their own home instead of the record.
        const ownerNote = {
          title: `${owner.program} owners updated`,
          body: `${owner.primaryName} is Primary Owner, with ${owner.backupName} as Backup Owner.`,
          category: "assignment" as const,
        };
        notify({ ...ownerNote, audience: ["site-contributor"], link: "/owners" });
        notify({ ...ownerNote, audience: ["administrator"], link: "/admin/sites/northstar" });
        setSavedName(owner.program); setEditing(null);
      }} />}
    </div>
  );
}

